39:     private boolean canCancel = true;
40:     private boolean showLog = true;
41:     private ArgumentBuilder args;
42: 
43:     public ProcessToolRunner(ProcessBuilder builder, String name, ModelItem modelItem, ArgumentBuilder args) {
44:         this(new ProcessBuilder[]{builder}, name, modelItem, args);
45:     }
46: 
47:     public ProcessToolRunner(ProcessBuilder[] builders, String name, ModelItem modelItem, ArgumentBuilder args) {
48:         this.builders = builders;
49:         this.name = name;
50:         this.modelItem = modelItem;
51:         this.args = args;
52:     }
53: 
54:     public ProcessToolRunner(ProcessBuilder[] processBuilders, String s, ModelItem modelItem) {
55:         this(processBuilders, s, modelItem, null);
56:     }
57: 
58:     public ProcessToolRunner(ProcessBuilder builder, String s, ModelItem modelItem) {
59:         this(builder, s, modelItem, null);
60:     }
61: 
62:     public ProcessBuilder[] getBuilders() {
63:         return builders;
64:     }
65: 
66:     public Process getProcess() {
67:         return process;
68:     }
69: 
70:     public boolean isRunning() {
71:         return running;
72:     }
73: 
74:     public void cancel() {
75:         getProcess().destroy();
76:         try {
77:             getProcess().waitFor();
78:         } catch (InterruptedException e) {
79:             e.printStackTrace();
80:         }
81: 
82:         running = false;
83:     }
84: 
85:     public void run() {
86:         try {
87:             int exitCode = -1;
88: 
89:             beforeRun(context);
90: 
91:             for (int c = 0; c < builders.length; c++) {
92:                 beforeProcess(builders[c], context);
93: 
94:                 logRunInfo(builders[c]);
95:                 process = builders[c].start();
96:                 if (c == 0) {
97:                     context.setStatus(RunnerContext.RunnerStatus.RUNNING);
98:                 }
99: 
100:                 running = true;
101: 
102:                 InputStream in = process.getInputStream();
103:                 InputStream err = process.getErrorStream();
104: 
105:                 exitCode = -1;
106: 
107:                 while (exitCode == -1 && running) {
108:                     try {
109:                         exitCode = process.exitValue();
110:                         break;
111:                     } catch (IllegalThreadStateException e) {
112:                     } finally {
113:                         while (in.available() > 0) {
114:                             byte[] data = new byte[in.available()];
115:                             in.read(data);
116: 
117:                             context.log(new String(data));
118:                         }
119: 
120:                         while (err.available() > 0) {
121:                             byte[] data = new byte[err.available()];
122:                             err.read(data);
123: 
124:                             context.logError(new String(data));
125:                         }
126:                     }
127: 
128:                     Thread.sleep(25);
129:                 }
130: 
131:                 afterProcess(process, context);
132:             }
133: 
134:             context.setStatus(RunnerContext.RunnerStatus.FINISHED);
135: 
136:             if (running) {
137:                 running = false;
138:                 afterRun(exitCode, context);
139:             }
140:         } catch (Exception ex) {
141:             context.setStatus(RunnerContext.RunnerStatus.ERROR);
142:             UISupport.showErrorMessage(ex);
143:             running = false;
144:             afterRun(-1, context);
145:         } finally {
146:             context.disposeContext();
147:         }
148:     }
149: 
150:     protected void beforeRun(RunnerContext context) {
151:     }
152: 
153:     protected void beforeProcess(ProcessBuilder processBuilder, RunnerContext context) {
154:         processBuilder.environment().put(STARTED_FROM_GUI, "true");
155:     }
156: 
157:     protected void afterProcess(Process process2, RunnerContext context) {
158:     }
