160:     protected void afterRun(int exitCode, RunnerContext context) {
161:         if (exitCode == 0) {
162:             UISupport.showInfoMessage("Execution finished successfully", context.getTitle());
163:         } else {
164:             UISupport.showInfoMessage("Execution finished with errorCode " + exitCode
165:                     + ",\r\nplease check log for error messages", context.getTitle());
166:         }
167:     }
168: 
169:     private void logRunInfo(ProcessBuilder builder) {
170:         context.log("directory: " + builder.directory().getAbsolutePath() + "\r\n");
171:         context.log("command: " + (args == null ? builder.command() : args) + "\r\n");
172:     }
